const message = ($json.body.message || '').toLowerCase();
let reply = '';
let chips = [];

if (message.includes('pindai') || message.includes('chip') || message.includes('korban')) {
  reply = 'Scanner cybernetic-mu berbunyi berdengung. Chip memori korban sengaja dibakar dengan EMP sesaat sebelum tewas, namun partisi data cadangan memuat kode terenkripsi: **\"PROJECT_EVE - SUB-LEVEL 4\"**.';
  chips = ['Dekripsi data PROJECT_EVE', 'Tanyakan PROJECT_EVE ke Android K-9', 'Cari sumber EMP di ruangan'];
} else if (message.includes('interogasi') || message.includes('android') || message.includes('k-9')) {
  reply = 'Android K-9 menatapmu dengan iris optik berkedip kuning: *\"Saya tidak melihat sosok penyerang, Detektif. Protokol keamanan penthouse di-override dari jarak jauh via subnet internal pada pukul 23:14.\"*';
  chips = ['Lacak subnet internal', 'Uji apakah AI berbohong', 'Minta log akses 24 jam'];
} else {
  reply = `Detektif Vane menindaklanjuti petunjuk: \"${$json.body.message}\". Kamu menemukan puntung rokok ilegal beraroma vanila neon di ventilasi pendingin.`;
  chips = ['Kirim sampel ke lab forensik', 'Kejar jejak ke balkon', 'Interogasi security gedung'];
}

return { json: { content: reply, chips: chips } };
